#include <set>
#include <functional>

int main() {
    // Type 1: Ascending order
    std::set<int, std::less<int>> coll1 = {1, 5, 3};

    // Type 2: Descending order
    std::set<int, std::greater<int>> coll2 = {1, 5, 3};

    // coll1 = coll2; // ERROR: Incompatible types

    // Initialization via range constructor (OK)
    std::set<int, std::less<int>> coll3(coll2.begin(), coll2.end());

    return 0;
}
